 "Tambor": "Tambour",
 "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">MEMBRANÓFONO</span><br><b>Tambor</b><br><span style=\"font-size:21px;color:#6d5c45\">Vibra una membrana tensa</span>": "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">MEMBRANOPHONE</span><br><b>Tambour</b><br><span style=\"font-size:21px;color:#6d5c45\">Une membrane tendue vibre</span>",
 "Arpa": "Harpe",
 "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">CORDÓFONO</span><br><b>Arpa</b><br><span style=\"font-size:21px;color:#6d5c45\">Vibran cuerdas tensas</span>": "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">CORDOPHONE</span><br><b>Harpe</b><br><span style=\"font-size:21px;color:#6d5c45\">Des cordes tendues vibrent</span>",
 "Flauta dulce": "Flûte à bec",
 "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">AERÓFONO</span><br><b>Flauta dulce</b><br><span style=\"font-size:21px;color:#6d5c45\">Vibra una columna de aire</span>": "<span style=\"font-family:'Courier New', Courier, monospace;font-size:16px;letter-spacing:1px;color:#c0392b\">AÉROPHONE</span><br><b>Flûte à bec</b><br><span style=\"font-size:21px;color:#6d5c45\">Une colonne d'air vibre</span>",
 "Sintetizador": "Synthétiseur",
